package ru.evolenta.pgs.worker;
import java.util.*;import java.nio.charset.StandardCharsets;import static ru.evolenta.pgs.worker.Util.*;

/** Resumable advertising import; each create has its own durable intent and stable identity. */
public final class ImportOperations {
    public static final String WORKER_CONTRACT="pgs-advertising-external-v1";
    private static final class Reference {final String ref,field;Reference(String ref,String field){this.ref=ref;this.field=field;}public String toString(){return "_worker_ref_:"+field+":"+ref;}}
    private static Object idRef(String ref){return new Reference(ref,"_id");}
    private static Object guidRef(String ref){return new Reference(ref,"guid");}
    private final CheckpointStore journal;private final Operations.Lease lease;private final boolean writes;private final String ui;
    public ImportOperations(CheckpointStore journal,Operations.Lease lease,boolean writes,String ui){this.journal=journal;this.lease=lease;this.writes=writes;this.ui=ui.replaceAll("/+$","");}
    public static String inputHash(Map<String,Object>d){return hash(obj("sheets",d.get("sheets"),"file",d.get("file"),"context",d.get("context"),"validationVersion",d.get("validationVersion")));}
    private Map<String,Object> unit(AdvertisingGuard g){Map<String,Object>o=g.organization;return obj("id",id(o),"name",clean(o.get("name")),"shortName",first(o.get("shortName"),o.get("name")),"inn",first(o.get("inn"),at(o,"additionalData.inn")),"ogrn",first(o.get("ogrn"),at(o,"additionalData.ogrn")),"kpp",first(o.get("kpp"),at(o,"additionalData.kpp")));}
    public Map<String,Object> apply(Context c)throws Exception{
        if(!writes)throw new IllegalStateException("Реестровые изменения отключены настройкой worker.writesEnabled");
        if(ui.isEmpty()||ui.contains("REPLACE")||!ui.startsWith("https://"))throw new IllegalArgumentException("Настройте HTTPS worker.uiBaseUrl до применения импорта");
        AdvertisingGuard guard=new AdvertisingGuard(c,true);Map<String,Object>d=copy(map(first(c.appeal.get("importDraft"),c.sub.get("rbuImportDraft"))));String fileId=clean(at(d,"file.id")),fileHash=clean(at(d,"file.sha256"));
        if(!fileId.equals(clean(first(at(c.appeal,"importFile._id"),at(c.appeal,"importFile.id"),at(c.appeal,"importFile.fileId")))))throw new IllegalArgumentException("В деле выбран другой файл; повторите валидацию");
        if(!Arrays.asList("VALIDATED","APPLYING","APPLIED").contains(clean(d.get("status")))||bool(d.get("validationBlocked"))||integer(d.get("validRows"))<=0||!AdvertisingValidator.CONTRACT.equals(d.get("validationVersion"))||!fileHash.equals(clean(d.get("validatedFileSha256"))))throw new IllegalArgumentException("Нет актуального допустимого результата валидации");
        Object confirm=first(at(c.xsd,"rbuImportConfirmation.confirmApply"),c.xsd.get("confirmApply"));if(!bool(confirm))throw new IllegalArgumentException("Подтвердите миграцию");
        if(!id(guard.organization).equals(clean(at(d,"context.organization._id")))||!key(at(d,"context.region")).equals(key(guard.region.get("regionName")))||!key(at(d,"context.municipality")).equals(key(guard.municipality.get("municipalityName"))))throw new IllegalArgumentException("Контекст изменился после проверки");
        String validationKey=clean(d.get("workerValidationKey"));Map<String,Object>validated=journal.read(validationKey);if(!c.command.processId.equals(validated.get("processId"))||!c.command.mainId.equals(validated.get("appealId"))||!inputHash(d).equals(validated.get("inputHash")))throw new IllegalArgumentException("Серверный снимок валидации отсутствует или изменён; выполните проверку повторно");
        if(validated.get("draft") instanceof Map){d=map(validated.get("draft"));if(bool(d.get("validationBlocked")))throw new IllegalArgumentException("Серверная валидация заблокировала файл");}
        lease.check();if(!fileHash.equals(sha(c.api.download(fileId,XlsxReader.MAX_FILE))))throw new IllegalArgumentException("Содержимое файла изменилось после проверки");
        String runKey=hash(obj("process",c.command.processId,"mainId",c.command.mainId,"file",fileHash,"operation","IMPORT"));Map<String,Object>state=journal.read(runKey);if(state.isEmpty()){state=obj("status","APPLYING","createdAt",now(),"cursor",0);journal.save(runKey,state);}String started=clean(state.get("createdAt"));
        List<Map<String,Object>>plan=plan(c,d,guard,started);if(plan.size()>2500)throw new IllegalArgumentException("Превышен лимит 2500 физических записей");String planHash=hash(plan);if(present(state.get("planHash"))&&!planHash.equals(state.get("planHash")))throw new IllegalArgumentException("План импорта изменился; продолжение запрещено");state.put("planHash",planHash);journal.save(runKey,state);
        Map<String,Map<String,Object>>created=new LinkedHashMap<String,Map<String,Object>>();int cursor=integer(state.get("cursor")),end=Math.min(plan.size(),cursor+50);if(cursor<0||cursor>plan.size())throw new IllegalArgumentException("Повреждён cursor импорта");
        // Resolve already-created dependencies without recreating them.
        for(int i=0;i<cursor;i++){Map<String,Object>item=plan.get(i);Map<String,Object>saved=journal.read(clean(item.get("operationKey")));if(!"COMPLETED".equals(saved.get("status")))throw new IllegalStateException("Контрольная точка записи отсутствует");created.put(clean(item.get("ref")),saved);}
        for(int i=cursor;i<end;i++){lease.check();Map<String,Object>item=plan.get(i);Map<String,Object>payload=map(resolve(item.get("payload"),created));Map<String,Object>saved=create(c,clean(item.get("collection")),clean(item.get("operationKey")),payload);saved.putAll(obj("sheetCode",item.get("sheetCode"),"sheetName",item.get("sheetName"),"rowNumber",item.get("rowNumber"),"recordPart",item.get("recordPart")));journal.save(clean(item.get("operationKey")),saved);created.put(clean(item.get("ref")),saved);state.put("cursor",i+1);journal.save(runKey,state);}
        boolean more=end<plan.size();if(!more){crossLinks(c,plan,created);state.put("status","APPLIED");state.put("completedAt",now());journal.save(runKey,state);}
        List<Object>records=new ArrayList<Object>();Set<String>sourceRows=new HashSet<String>();Map<String,Object>byCollection=obj();for(Map<String,Object>item:plan){Map<String,Object>saved=created.get(clean(item.get("ref")));if(saved==null)continue;String collection=clean(item.get("collection"));Map<String,Object>record=c.api.find(collection,clean(saved.get("_id")));if(record.isEmpty())throw new IllegalStateException("Созданная запись исчезла: "+collection+"/"+saved.get("_id"));records.add(obj("collection",collection,"_id",id(record),"guid",record.get("guid"),"sheetCode",item.get("sheetCode"),"sheetName",item.get("sheetName"),"rowNumber",item.get("rowNumber"),"recordPart",item.get("recordPart"),"createdAt",started,"operationKey",item.get("operationKey"),"businessHash",businessHash(record)));sourceRows.add(item.get("sheetCode")+":"+item.get("rowNumber"));byCollection.put(collection,integer(byCollection.get(collection))+1);}
        d.put("status",more?"APPLYING":"APPLIED");d.put("batchProgress",obj("status",more?"PROCESSING":"COMPLETED","nextOffset",end,"totalRecords",plan.size(),"fileSha256",fileHash,"updatedAt",now()));Map<String,Object>result=copy(map(c.sub.get("rbuImportResult")));result.putAll(obj("processingStatus",more?"Миграция выполняется":"Миграция завершена","applicationStatus",d.get("status"),"createdRows",sourceRows.size(),"reusedRows",0,"skippedRows",more?0:Math.max(0,integer(d.get("validRows"))-sourceRows.size()),"processedAt",now()));Map<String,Object>summary=obj("workerContract",WORKER_CONTRACT,"workerRunKey",runKey,"status",d.get("status"),"dataType","Реклама","recordCount",records.size(),"createdRows",sourceRows.size(),"recordsByCollection",byCollection,"updatedAt",now());if(!more)summary.put("completedAt",state.get("completedAt"));Map<String,Object>publicDraft=Operations.compactDraft(d);lease.check();c.saveAppeal(obj("importDraft",publicDraft,"applicationStatus",d.get("status"),"migrationLog",result.get("migrationLog")));c.saveResult(publicDraft,result);c.saveSub(obj("migrationCreatedRecords",records,"advertisingMigrationSummary",summary));
        return obj("rbuApplicationStatus",d.get("status"),"rbuCreatedRows",sourceRows.size(),"rbuReusedRecords",0,"rbuSkippedRows",result.get("skippedRows"),"rbuApplyHasMoreBatches",more,"rbuApplyRowCursor",end,"rbuApplyRejected",false,"rbuApplyError","");
    }
    private List<Map<String,Object>> plan(Context c,Map<String,Object>d,AdvertisingGuard guard,String started)throws Exception{
        Payloads p=new Payloads(c.appeal);List<Payloads.Row>permissions=new ArrayList<Payloads.Row>();for(Map<String,Object>s:maps(d.get("sheets")))if("sheet3".equals(s.get("code")))for(Map<String,Object>r:maps(s.get("rows")))permissions.add(new Payloads.Row(s,r));List<Map<String,Object>>out=new ArrayList<Map<String,Object>>();
        for(Map<String,Object>s:maps(d.get("sheets")))for(Map<String,Object>row:maps(s.get("rows"))){if(!"VALID".equals(row.get("validationStatus")))continue;Payloads.Row r=new Payloads.Row(s,row);String code=clean(s.get("code"));if(code.equals("sheet2")){Map<String,Object>place=p.place(r,permissions);String ref=add(out,c,d,guard,s,row,"placeReestrRKCollection","place",place,started);String status=clean(at(place,"infoRK.placeStatus.name"));String coord=clean(at(place,"infoRK.coordinates"));String[]parts=coord.split(",");boolean validCoord=parts.length==2&&number(parts[0])!=null&&number(parts[1])!=null&&number(parts[0]).abs().doubleValue()<=90&&number(parts[1]).abs().doubleValue()<=180;if(validCoord&&Arrays.asList("Утверждено","Ликвидировано").contains(status))add(out,c,d,guard,s,row,"nsiUnifiedPGS_object_marketing","nsi",nsi(place,ref),started);add(out,c,d,guard,s,row,"biddingReestrRKCollection","bidding",p.bidding(r),started);add(out,c,d,guard,s,row,"contractReestrRKCollection","contract",p.contract(r),started);add(out,c,d,guard,s,row,"obligationReestrRKCollection","obligation",p.obligation(r),started);}else if(code.equals("sheet3")){Map<String,Object>root=p.permission(r),license=copy(root);Map<String,Object>nested=map(license.remove("license"));license.remove("licenseId");license.remove("operationType");license.put("orderData",nested.get("orderData"));String ref=add(out,c,d,guard,s,row,"marketingLicenses","license",license,started);Map<String,Object>registry=copy(root);registry.put("licenseId",idRef(ref));registry.put("status","active");add(out,c,d,guard,s,row,"marketingRegistry","registry",registry,started);}else if(code.equals("sheet4"))add(out,c,d,guard,s,row,"socialAdReestrRKCollection","social",p.social(r),started);else if(code.equals("sheet5"))add(out,c,d,guard,s,row,"unauthorizedReestrRKCollection","noPermission",p.noPermission(r,false),started);else if(code.equals("sheet6"))add(out,c,d,guard,s,row,"dismantleReestrRKCollection","dismantling",p.noPermission(r,true),started);}
        return out;
    }
    private String add(List<Map<String,Object>>out,Context c,Map<String,Object>d,AdvertisingGuard guard,Map<String,Object>sheet,Map<String,Object>row,String collection,String part,Map<String,Object>payload,String started){String ref=sheet.get("code")+":"+row.get("rowNumber")+":"+part;if(payload==null)return ref;String key=hash(obj("process",c.command.processId,"appeal",c.command.mainId,"file",at(d,"file.sha256"),"collection",collection,"ref",ref));Map<String,Object>record=new LinkedHashMap<String,Object>(payload);record.put("guid",UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString());record.put("parentEntries",collection);record.put("unit",unit(guard));record.put("migrationSource",obj("workerContract",WORKER_CONTRACT,"appealId",c.command.mainId,"appealNumber",c.appeal.get("number"),"parserVersion",d.get("parserVersion"),"validationVersion",d.get("validationVersion"),"sourceFile",at(d,"file.originalName"),"sourceFileId",at(d,"file.id"),"sourceFileSha256",at(d,"file.sha256"),"rowHash",hash(row),"sheetCode",sheet.get("code"),"sheetName",sheet.get("sheetName"),"rowNumber",row.get("rowNumber"),"recordPart",part.equals("license")||part.equals("registry")||part.equals("nsi")?part:null,"operationKey",key,"appliedAt",started));if(part.equals("nsi")){record.put("_id",payload.get("_id"));record.put("guid",payload.get("guid"));}out.add(obj("ref",ref,"operationKey",key,"collection",collection,"sheetCode",sheet.get("code"),"sheetName",sheet.get("sheetName"),"rowNumber",row.get("rowNumber"),"recordPart",at(record,"migrationSource.recordPart"),"payload",record));return ref;}
    private Object resolve(Object value,Map<String,Map<String,Object>>created){if(value instanceof Reference){Reference reference=(Reference)value;Map<String,Object>record=created.get(reference.ref);if(record==null)throw new IllegalStateException("Не создана зависимость: "+reference.ref);return record.get(reference.field);}if(value instanceof Map){Map<String,Object>m=obj();for(Map.Entry<String,Object>e:map(value).entrySet())m.put(e.getKey(),resolve(e.getValue(),created));return m;}if(value instanceof List){List<Object>a=new ArrayList<Object>();for(Object x:list(value))a.add(resolve(x,created));return a;}return value;}
    private Map<String,Object>create(Context c,String collection,String key,Map<String,Object>payload)throws Exception{
        Map<String,Object>saved=journal.read(key);List<Object>filters=new ArrayList<Object>();filters.add(Context.filter("migrationSource.operationKey",key));List<Map<String,Object>>found=c.api.search(collection,filters,0,2);if(found.size()>1)throw new IllegalStateException("Дубли operationKey, необходим ручной разбор");if(found.size()==1){Map<String,Object>record=found.get(0);if(!c.command.mainId.equals(clean(at(record,"migrationSource.appealId")))||!clean(at(payload,"migrationSource.sourceFileSha256")).equals(clean(at(record,"migrationSource.sourceFileSha256"))))throw new IllegalStateException("Конфликт идентичности импортируемой записи");Map<String,Object>done=obj("status","COMPLETED","collection",collection,"_id",id(record),"guid",record.get("guid"),"operationKey",key);journal.save(key,done);return done;}
        if(!saved.isEmpty())throw new IllegalStateException("Неопределённый результат ранее начатого CREATE: "+collection+". Повторный CREATE запрещён, проверьте журнал "+key);
        lease.check();journal.save(key,obj("status","CREATE_PENDING","collection",collection,"guid",payload.get("guid"),"operationKey",key,"startedAt",now()));Map<String,Object>record=c.api.create(collection,payload);if(id(record).isEmpty())throw new IllegalStateException("CREATE не вернул идентификатор; повтор запрещён до сверки");Map<String,Object>done=obj("status","COMPLETED","collection",collection,"_id",id(record),"guid",first(record.get("guid"),payload.get("guid")),"operationKey",key);journal.save(key,done);return done;
    }
    public static String businessHash(Map<String,Object>record){Map<String,Object>m=copy(record);for(String name:Arrays.asList("_id","auid","guid","dateCreation","dateLastModification","lastChangedAt","userCreation","userLastModification","lastChangedByAppealId"))m.remove(name);return hash(m);}
    private Map<String,Object>nsi(Map<String,Object>place,String ref){Map<String,Object>info=map(place.get("infoRK")),bidding=map(place.get("biddingInfo")),solution=map(place.get("solutionInfo")),operator=map(place.get("operatorInfo"));Map<String,Object>n=obj("Layer","Реклама","dictionaryType","unified","dictionaryUnitId",null,"Subject",at(place,"totalInfo.subject"),"Disctrict",at(place,"totalInfo.municipality"),"RKNumber",info.get("numberRK"),"RKType",at(info,"typeRK.name"),"RKKind",first(info.get("kindRKOther"),at(info,"kindRK.name")),"GeoCoordinates",info.get("coordinates"),"RKSquare",info.get("totalArea"),"RKSides",at(info,"sidesAmount.name"),"FullAddress",at(info,"address.fullAddress"),"CadNumber",info.get("cadastralNum"),"PropertyType",at(info,"propertyType.name"),"SpecificationStatusRK",at(info,"placeStatusSpecific.name"),"ContractNumber",bidding.get("contractNum"),"ContractStartDate",displayDate(bidding.get("contractStartDate")),"ContractEndDate",displayDate(bidding.get("contractEndDate")),"TradingData",bidding.get("linkToTrade"),"PermitNumber",solution.get("permissionNumber"),"PermitStatus",solution.get("solutionStatus"),"PermitData",displayDate(solution.get("solutionStartDate")),"PermitEndData",displayDate(solution.get("solutionEndDate")),"OperatorINN","","OperatorOGRN","","OperatorName","","_id",idRef(ref),"code",idRef(ref),"guid",guidRef(ref),"ObjectID",idRef(ref));String a=clean(operator.get("applicantList"));if(a.equals("Юридическое лицо")){Map<String,Object>d=map(operator.get("operatorDataUL"));n.putAll(obj("OperatorINN",d.get("inn"),"OperatorOGRN",d.get("ogrn"),"OperatorName",d.get("name")));}else if(a.equals("Индивидуальный предприниматель")){Map<String,Object>d=map(operator.get("operatorDataIP"));n.putAll(obj("OperatorINN",d.get("inn"),"OperatorOGRN",d.get("ogrnIP"),"OperatorName",d.get("nameIP")));}return n;}
    private Object displayDate(Object value){String s=clean(value);if(s.length()>=10&&s.charAt(4)=='-'&&s.charAt(7)=='-')return s.substring(8,10)+"."+s.substring(5,7)+"."+s.substring(0,4);return date(s)==null?null:s;}
    private void crossLinks(Context c,List<Map<String,Object>>plan,Map<String,Map<String,Object>>created)throws Exception{if(ui.isEmpty()||ui.contains("REPLACE"))throw new IllegalArgumentException("Настройте worker.uiBaseUrl до применения импорта");for(Map<String,Object>item:plan){String collection=clean(item.get("collection")),ref=clean(item.get("ref")),rowPrefix=ref.substring(0,ref.lastIndexOf(':')+1);Map<String,Object>record=created.get(ref),place=created.get(rowPrefix+"place"),bidding=created.get(rowPrefix+"bidding");if(collection.equals("placeReestrRKCollection"))patch(c,collection,record,"infoRK.urlEPGU","https://gosuslugi.ru/ad/"+record.get("_id"));else if(collection.equals("biddingReestrRKCollection")&&place!=null)patch(c,"placeReestrRKCollection",place,"biddingInfo.biddingNumber",ui+"/marketing/marketingReestrs/reestrBidding/edit/"+record.get("_id"));else if(collection.equals("contractReestrRKCollection")&&bidding!=null)patch(c,"biddingReestrRKCollection",bidding,"procedureInfo.bidProcedureInfo.linkContractRecord",ui+"/marketing/marketingReestrs/reestrContracts/edit/"+record.get("_id"));else if(collection.equals("obligationReestrRKCollection")&&place!=null)patch(c,"placeReestrRKCollection",place,"placeNegotiationInfo",Arrays.asList(obj("obligationLink",ui+"/marketing/marketingReestrs/reestrObligations/edit/"+record.get("_id"))));}}
    private void patch(Context c,String collection,Map<String,Object>identity,String field,Object value)throws Exception{lease.check();Map<String,Object>record=c.api.find(collection,clean(identity.get("_id")));if(!c.command.mainId.equals(clean(at(record,"migrationSource.appealId"))))throw new IllegalStateException("Запись кросс-ссылки не принадлежит миграции");Util.put(record,field,value);String root=field.split("\\.")[0];c.api.update(collection,id(record),clean(record.get("guid")),obj(root,record.get(root)));}
    public Map<String,Object>finalizeImport(Context c)throws Exception{Map<String,Object>summary=map(c.sub.get("advertisingMigrationSummary"));String runKey=hash(obj("process",c.command.processId,"mainId",c.command.mainId,"file",at(c.appeal,"importDraft.file.sha256"),"operation","IMPORT"));if(!"APPLIED".equals(journal.read(runKey).get("status")))throw new IllegalStateException("Нет серверной контрольной точки завершённого импорта");if(!"APPLIED".equals(summary.get("status")))throw new IllegalStateException("Импорт не завершён; журнал не может быть финализирован");return obj("rbuApplicationStatus","APPLIED","rbuApplyHasMoreBatches",false,"rbuCreatedRows",integer(summary.get("createdRows")));}
}
